BEGIN; DO $$ DECLARE v_public_def text; BEGIN IF to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NULL THEN RAISE EXCEPTION 'Thieu ham inventory_soft_delete_manual_transactions(uuid[]).'; END IF; IF to_regprocedure('public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])') IS NULL THEN RAISE EXCEPTION 'Thieu legacy core inventory_soft_delete_manual_transactions_core_20260722(uuid[]).'; END IF; IF to_regprocedure('public.inventory_assert_no_negative_product_after(uuid,date)') IS NULL OR to_regprocedure('public.inventory_lock_product(uuid)') IS NULL THEN RAISE EXCEPTION 'Thieu hang rao ton kho theo tong ma hang.'; END IF; IF to_regprocedure('public.inventory_actor_can_change_transaction(date)') IS NULL THEN RAISE EXCEPTION 'Thieu ham kiem tra quyen sua giao dich kho.'; END IF; SELECT pg_get_functiondef(to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])')) INTO v_public_def; IF v_public_def NOT ILIKE '%inventory_soft_delete_manual_transactions_core_20260722%' AND v_public_def NOT ILIKE '%inventory_assert_no_negative_product_after%' THEN RAISE EXCEPTION 'Ham live khong khop wrapper cu va cung chua phai ban fix theo tong ma. Dung lai de audit.'; END IF; END $$; CREATE OR REPLACE FUNCTION public.inventory_soft_delete_manual_transactions(p_transaction_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_user_id uuid:=auth.uid(); v_now timestamptz:=now(); v_requested_count integer; v_distinct_count integer; v_locked_count integer; v_base_count integer:=0; v_adjust_count integer:=0; v_key record; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Ban can dang nhap de huy giao dich kho.' USING ERRCODE='42501'; END IF; IF p_transaction_ids IS NULL OR cardinality(p_transaction_ids)=0 OR array_position(p_transaction_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Danh sach giao dich can huy khong hop le.'; END IF; v_requested_count:=cardinality(p_transaction_ids); IF v_requested_count>100 THEN RAISE EXCEPTION 'Moi lan chi duoc huy toi da 100 giao dich kho.'; END IF; SELECT count(DISTINCT x.id) INTO v_distinct_count FROM unnest(p_transaction_ids) AS x(id); IF v_distinct_count<>v_requested_count THEN RAISE EXCEPTION 'Danh sach giao dich bi trung lap.'; END IF; PERFORM t.id FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) AND t.deleted_at IS NULL ORDER BY t.id FOR UPDATE; GET DIAGNOSTICS v_locked_count=ROW_COUNT; IF v_locked_count<>v_requested_count THEN RAISE EXCEPTION 'Co giao dich khong ton tai hoac da duoc huy. Khong giao dich nao thay doi.'; END IF; IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) AND t.deleted_at IS NULL AND (t.tx_type NOT IN('in','out') OR t.adjusted_from_transaction_id IS NOT NULL)) THEN RAISE EXCEPTION 'Chi duoc huy giao dich nhap/xuat kho goc.'; END IF; IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) AND t.deleted_at IS NULL AND (t.shipment_id IS NOT NULL OR t.delivery_plan_id IS NOT NULL)) THEN RAISE EXCEPTION 'Giao dich thuoc chuyen hang hoac ke hoach giao hang. Vui long dieu chinh tai Nhat ky giao hang.'; END IF; IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) AND t.deleted_at IS NULL AND t.stocktake_id IS NOT NULL) THEN RAISE EXCEPTION 'Giao dich thuoc phieu kiem ke. Vui long dieu chinh tai phieu kiem ke.'; END IF; IF EXISTS(SELECT 1 FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) AND t.deleted_at IS NULL AND NOT public.inventory_actor_can_change_transaction(t.tx_date::date)) THEN RAISE EXCEPTION 'Ban khong co quyen huy mot hoac nhieu giao dich da chon.' USING ERRCODE='42501'; END IF; PERFORM a.id FROM public.inventory_transactions a WHERE a.adjusted_from_transaction_id=ANY(p_transaction_ids) AND a.deleted_at IS NULL ORDER BY a.id FOR UPDATE; FOR v_key IN SELECT affected.product_id,min(affected.tx_date)::date AS tx_date FROM(SELECT t.product_id,t.tx_date FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) UNION ALL SELECT a.product_id,a.tx_date FROM public.inventory_transactions a WHERE a.adjusted_from_transaction_id=ANY(p_transaction_ids) AND a.deleted_at IS NULL) affected GROUP BY affected.product_id ORDER BY affected.product_id LOOP IF v_key.product_id IS NULL THEN RAISE EXCEPTION 'Giao dich kho bi thieu ma hang. Dung lai de kiem tra.'; END IF; PERFORM public.inventory_lock_product(v_key.product_id); END LOOP; PERFORM set_config('app.inventory_batch_replace','on',true); UPDATE public.inventory_transactions a SET deleted_at=v_now,deleted_by=v_user_id,updated_at=v_now,updated_by=v_user_id,note=concat_ws(' | ',NULLIF(a.note,''),'Huy theo giao dich goc luc '||v_now::text) WHERE a.adjusted_from_transaction_id=ANY(p_transaction_ids) AND a.deleted_at IS NULL; GET DIAGNOSTICS v_adjust_count=ROW_COUNT; UPDATE public.inventory_transactions t SET deleted_at=v_now,deleted_by=v_user_id,updated_at=v_now,updated_by=v_user_id,note=concat_ws(' | ',NULLIF(t.note,''),'Huy giao dich luc '||v_now::text) WHERE t.id=ANY(p_transaction_ids) AND t.deleted_at IS NULL; GET DIAGNOSTICS v_base_count=ROW_COUNT; IF v_base_count<>v_requested_count THEN RAISE EXCEPTION 'Khong huy du so giao dich da chon. Toan bo thao tac duoc hoan tac.'; END IF; PERFORM set_config('app.inventory_batch_replace','off',true); FOR v_key IN SELECT affected.product_id,min(affected.tx_date)::date AS tx_date FROM(SELECT t.product_id,t.tx_date FROM public.inventory_transactions t WHERE t.id=ANY(p_transaction_ids) UNION ALL SELECT a.product_id,a.tx_date FROM public.inventory_transactions a WHERE a.adjusted_from_transaction_id=ANY(p_transaction_ids)) affected GROUP BY affected.product_id ORDER BY affected.product_id LOOP PERFORM public.inventory_assert_no_negative_product_after(v_key.product_id,v_key.tx_date); END LOOP; RETURN jsonb_build_object('success',true,'soft_deleted_count',v_base_count,'soft_deleted_adjustment_count',v_adjust_count,'message','Da huy giao dich kho. Lich su van duoc giu lai.'); EXCEPTION WHEN OTHERS THEN PERFORM set_config('app.inventory_batch_replace','off',true); RAISE; END $$; REVOKE ALL ON FUNCTION public.inventory_soft_delete_manual_transactions(uuid[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.inventory_soft_delete_manual_transactions(uuid[]) TO authenticated; REVOKE ALL ON FUNCTION public.inventory_soft_delete_manual_transactions_core_20260722(uuid[]) FROM PUBLIC,anon,authenticated; NOTIFY pgrst,'reload schema'; COMMIT;
